import{_ as a,o as s,c as o,a2 as n}from"./chunks/framework.DxR7mb1F.js";const t="/bluebook/assets/showreel-sphere.FhRV1zOZ.png",i="/bluebook/assets/showreel-scene.B9IRTOOt.png",b=JSON.parse('{"title":"用 WorkBuddy 生成一个 GSAP 粒子球体作品集动画网站","description":"年底需要做一份工作室年度作品集 Showreel。传统的做法是用 After Effects 或 Premiere 手动剪辑，但这类工具对动效交互和 3D 视觉的迭代成本很高——每次调整缓动曲线或粒子参数都要重新渲染。","frontmatter":{"title":"用 WorkBuddy 生成一个 GSAP 粒子球体作品集动画网站","summary":"从一份脚本和 27 个本地素材出发，经过 17 轮迭代，在 WorkBuddy 中完成一个可在线预览的 3D 粒子球体 Showreel 动画网站，最终推送到 GitHub 并启用 Pages。","author":"JZCreative","date":"2026-07-15","category":"创意开发","difficulty":"进阶","aside":false,"outline":false,"skills":["本地文件读写","本地 HTTP 服务器","Git 推送与 GitHub Pages"],"tags":["GSAP","3D 动画","作品集","HTML","GitHub Pages","迭代优化"]},"headers":[],"relativePath":"cases/submissions/jz-2025-showreel/index.md","filePath":"cases/submissions/jz-2025-showreel/index.md","lastUpdated":1786934056000}'),l={name:"cases/submissions/jz-2025-showreel/index.md"};function r(d,e,p,c,h,u){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="用-workbuddy-生成一个-gsap-粒子球体作品集动画网站" tabindex="-1">用 WorkBuddy 生成一个 GSAP 粒子球体作品集动画网站 <a class="header-anchor" href="#用-workbuddy-生成一个-gsap-粒子球体作品集动画网站" aria-label="Permalink to &quot;用 WorkBuddy 生成一个 GSAP 粒子球体作品集动画网站&quot;">​</a></h1><h2 id="场景描述" tabindex="-1">场景描述 <a class="header-anchor" href="#场景描述" aria-label="Permalink to &quot;场景描述&quot;">​</a></h2><p>年底需要做一份工作室年度作品集 Showreel。传统的做法是用 After Effects 或 Premiere 手动剪辑，但这类工具对动效交互和 3D 视觉的迭代成本很高——每次调整缓动曲线或粒子参数都要重新渲染。</p><p>我希望换一种方式：用 GSAP + 软件 3D 投影做一个纯前端动画，300 个粒子聚拢成球体，6 个节点代表 6 组作品，点击节点后镜头聚焦、标题浮出、作品视频展开。整个过程在浏览器里实时运行，可以随时调整参数立即看到效果。</p><p>但手写这个动画的 3D 数学、粒子分布、时间线编排和 Mockup 布局非常耗时。所以我把它交给 WorkBuddy，用自然语言描述需求，让它逐步生成并迭代。</p><h2 id="想要完成的任务" tabindex="-1">想要完成的任务 <a class="header-anchor" href="#想要完成的任务" aria-label="Permalink to &quot;想要完成的任务&quot;">​</a></h2><ul><li><strong>输入</strong>：一份 6 场景脚本（含标题、副标题、作品名、链接），27 个本地媒体文件（MP4/MOV 视频 + 截图）</li><li><strong>目标</strong>：一个自包含 HTML 文件 + 本地媒体，在浏览器中实时播放粒子球体 Showreel 动画</li><li><strong>交付物</strong>： <ul><li>可在浏览器中预览的 HTML 动画</li><li>推送到 GitHub 仓库并通过 GitHub Pages 在线访问</li></ul></li></ul><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>WorkBuddy 版本：支持本地文件读写和 Bash 执行的版本</li><li>操作系统：macOS（Windows/Linux 同样适用，路径稍作调整）</li><li>所需账号或权限：GitHub 账号，已配置 SSH key 或 personal access token</li><li>所需输入文件：27 个媒体文件放在本地文件夹，一份脚本文本</li></ul><h2 id="使用的-skill" tabindex="-1">使用的 Skill <a class="header-anchor" href="#使用的-skill" aria-label="Permalink to &quot;使用的 Skill&quot;">​</a></h2><p>本次任务没有安装额外的 Skill，全程使用 WorkBuddy 的内置能力：</p><table tabindex="0"><thead><tr><th>能力</th><th>用途</th><th>来源或安装方式</th></tr></thead><tbody><tr><td>本地文件读写</td><td>读取素材文件、写入生成的 HTML</td><td>WorkBuddy 内置</td></tr><tr><td>Bash 执行</td><td>启动 HTTP 服务器、检查视频尺寸、Git 操作</td><td>WorkBuddy 内置</td></tr><tr><td>网页预览</td><td>在浏览器中实时预览动画效果</td><td>WorkBuddy 内置</td></tr><tr><td>GSAP CDN 引用</td><td>通过 <code>&lt;script&gt;</code> 标签引入 GSAP 3.12.5</td><td>外部 CDN（cdnjs）</td></tr></tbody></table><h2 id="在-workbuddy-中的操作" tabindex="-1">在 WorkBuddy 中的操作 <a class="header-anchor" href="#在-workbuddy-中的操作" aria-label="Permalink to &quot;在 WorkBuddy 中的操作&quot;">​</a></h2><h3 id="第一步-描述需求并提供素材路径" tabindex="-1">第一步：描述需求并提供素材路径 <a class="header-anchor" href="#第一步-描述需求并提供素材路径" aria-label="Permalink to &quot;第一步：描述需求并提供素材路径&quot;">​</a></h3><p>我把脚本和素材路径发给 WorkBuddy：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我准备设计一个工作室作品集动画视频，标题是「JZ Creative Studio 2025 Showreel」。</span></span>
<span class="line"><span>要求：浅色背景 + 点线 MG 设计，开场形成一个基于 GSAP 的大型粒子球体，</span></span>
<span class="line"><span>球面上有节点代表作品组，聚焦节点后弹出作品视频。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>脚本：</span></span>
<span class="line"><span>场景1 - SVG 交互设计（蕉内 / 香奈儿 / 喜茶）</span></span>
<span class="line"><span>场景2 - H5 互动页面（中国新闻网 / 互动叙事H5）</span></span>
<span class="line"><span>场景3 - Vibe Coding（在线技能五子棋）</span></span>
<span class="line"><span>场景4 - AIGC 创意设计（数据可视化 / 航天科普 / 政务漫画）</span></span>
<span class="line"><span>场景5 - AI 创新方法论（编程式快闪 / 音乐Remix / SVG融合）</span></span>
<span class="line"><span>场景6 - 复旦百廿·母校礼赞（复旦120周年专题）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>素材都在本地文件夹：/Users/yaoyao/Documents/Marshall工作文档/运营/Showreel/2025</span></span></code></pre></div><p>WorkBuddy 读取了素材目录，生成了第一版 HTML，并启动了本地 HTTP 服务器让我预览。</p><h3 id="第二步-迭代调整视觉与动画" tabindex="-1">第二步：迭代调整视觉与动画 <a class="header-anchor" href="#第二步-迭代调整视觉与动画" aria-label="Permalink to &quot;第二步：迭代调整视觉与动画&quot;">​</a></h3><p>第一版出来后，我开始逐轮反馈。以下是关键的迭代节点：</p><p><strong>第 2-3 轮</strong>：颜色太多 → 改为 Apple 黑白灰（<code>#1D1D1F</code> / <code>#86868B</code> / <code>#F5F5F7</code>）；只有开场没有转场 → 补全 6 个场景的完整流程。</p><p><strong>第 4-5 轮</strong>：节点用 CSS 3D Transform 会随球体翻转被压扁 → 放弃 CSS 3D，改为纯 JS 软件 3D 投影（手动旋转矩阵 + 透视投影），节点用 2D <code>translate()</code> 定位，只同步位置不翻转。</p><p><strong>第 6-7 轮</strong>：节点视觉上在球体之外 → 使用 Fibonacci 球面粒子索引直接替换对应位置的粒子，确保节点在球面上；增加坐标轴、大圆参考线、倾斜轨道、粒子间虚线连接等装饰。</p><p><strong>第 8-9 轮</strong>：Mockup 风格不统一 → 统一为浏览器窗口线框风格（标题栏 + 圆点 + URL + 内容区）；通过 <code>sips</code> 命令检查所有截图实际像素尺寸，修正竖版/横版比例。</p><p><strong>第 10-11 轮</strong>：作品展示面积太小 → 放大 Mockup 尺寸并增加漂浮动画；标题从节点位置浮出，带连接线和持续漂浮。</p><p><strong>第 12 轮</strong>：页面空白打不开 → JS 语法错误（<code>},0})</code> 漏了一个 <code>}</code>），修复后正常。</p><p><strong>第 13-14 轮</strong>：动画太快 → 全局减速 1.5-2 倍，缓动改用 <code>power4.inOut</code> / <code>back.out(1.2)</code>；五子棋视频被裁切 → Mockup 内容区比例精确匹配视频比例（780×528 对应 1.560）。</p><p><strong>第 15-16 轮</strong>：节点进入球体内部 → 投影坐标乘以 0.82 使节点视觉上嵌入球面；结尾 LOGO 替换为水墨头像 PNG；字体改为阿里巴巴普惠体 2.0。</p><p><strong>第 17 轮</strong>：放大动画不显示 → 发现 GSAP timeline 中退出和新场景的 <code>camS</code> tween 各自创建独立临时对象，导致起始值=终值无渐变 → 改为共享同一对象修复。</p><h3 id="第三步-推送到-github-并启用-pages" tabindex="-1">第三步：推送到 GitHub 并启用 Pages <a class="header-anchor" href="#第三步-推送到-github-并启用-pages" aria-label="Permalink to &quot;第三步：推送到 GitHub 并启用 Pages&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这个项目和关联资产都推到我的 GitHub 仓库：</span></span>
<span class="line"><span>https://github.com/JZCreative/2025showreel</span></span></code></pre></div><p>WorkBuddy 自动完成了：</p><ol><li>创建 <code>.gitignore</code>（排除 node_modules、构建产物）</li><li><code>git init</code> + <code>git add</code> + <code>git commit</code></li><li><code>git push</code>（414MB 媒体文件，约 4 分钟上传完成）</li><li>通过 GitHub API 启用 Pages</li><li>创建 <code>index.html</code> 重定向页面</li></ol><h3 id="提示词或任务指令" tabindex="-1">提示词或任务指令 <a class="header-anchor" href="#提示词或任务指令" aria-label="Permalink to &quot;提示词或任务指令&quot;">​</a></h3><p>以下是经过脱敏、可以复用的核心任务指令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设计一个工作室作品集动画，要求：</span></span>
<span class="line"><span>- 浅色背景 + 点线 MG 设计风格</span></span>
<span class="line"><span>- 开场：GSAP 驱动的 3D 粒子球体（300 个粒子，Fibonacci 分布）</span></span>
<span class="line"><span>- 球面上 6 个节点代表 6 组作品</span></span>
<span class="line"><span>- 聚焦节点：球体旋转 → 镜头缩放 → 节点放大 → 标题浮出 → Mockup 展开</span></span>
<span class="line"><span>- 颜色：Apple 黑白灰（#1D1D1F / #86868B / #F5F5F7）</span></span>
<span class="line"><span>- 字体：阿里巴巴普惠体 2.0</span></span>
<span class="line"><span>- 键盘控制：Space 播放暂停 / ← → 切换场景 / Esc 跳结尾</span></span>
<span class="line"><span>- 结尾：粒子消散，水墨头像淡入</span></span>
<span class="line"><span></span></span>
<span class="line"><span>素材路径：[本地文件夹路径]</span></span></code></pre></div><p>迭代阶段的典型反馈指令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>节点看起来还是在粒子球之外，让它们进入球体内部；</span></span>
<span class="line"><span>五子棋视频被裁切了，调整 Mockup 比例匹配视频；</span></span>
<span class="line"><span>动画整体太快，慢一些更丝滑；</span></span>
<span class="line"><span>结尾 LOGO 替换为这个 PNG。</span></span></code></pre></div><h2 id="在-workbuddy-中的效果" tabindex="-1">在 WorkBuddy 中的效果 <a class="header-anchor" href="#在-workbuddy-中的效果" aria-label="Permalink to &quot;在 WorkBuddy 中的效果&quot;">​</a></h2><p>最终交付物：</p><ul><li><strong>主文件</strong>：<code>showreel-preview.html</code>（约 33KB，自包含 HTML + CSS + JS）</li><li><strong>媒体资产</strong>：<code>public/works/</code> 下 27 个文件（13 视频 + 14 截图）</li><li><strong>在线预览</strong>：<a href="https://jzcreative.github.io/2025showreel/" target="_blank" rel="noreferrer">https://jzcreative.github.io/2025showreel/</a></li><li><strong>GitHub 仓库</strong>：<a href="https://github.com/JZCreative/2025showreel" target="_blank" rel="noreferrer">https://github.com/JZCreative/2025showreel</a></li></ul><p>动画效果概述：</p><p><img src="`+t+'" alt="粒子球体形成后的初始画面" loading="lazy"></p><p><em>300 个粒子聚拢成球体，带坐标轴、大圆参考线和粒子间虚线连接。</em></p><p><img src="'+i+'" alt="场景展示效果" loading="lazy"></p><p><em>聚焦节点后，标题从节点浮出，Mockup 浏览器窗口沿分支线展开，右上角信息面板实时显示旋转数据。</em></p><ul><li>300 个粒子从随机散开位置聚拢成球体（3 秒，<code>power4.out</code>）</li><li>球体缓慢自转，带坐标轴、大圆参考线、粒子间虚线连接</li><li>点击节点或按 <code>→</code> 切换场景：球体旋转将目标节点转到正面（1.8 秒，<code>power4.inOut</code>）</li><li>镜头缩放至 1.3x，节点放大 1.8x（<code>back.out(1.2)</code> 回弹）</li><li>标题从节点位置浮出到左上角，带贝塞尔曲线连接线</li><li>Mockup 浏览器窗口沿分支线展开，持续 sine.inOut 漂浮</li><li>右上角信息面板实时显示旋转角度、缩放倍率、当前节点</li></ul><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><ul><li>[x] 浏览器中打开能正常播放 6 个场景的完整动画</li><li>[x] 粒子球体旋转流畅，节点在球面内部</li><li>[x] 每个场景的视频比例正确，无裁切</li><li>[x] 键盘控制（Space / ← → / Esc）正常响应</li><li>[x] 播放到结尾后不自动循环</li><li>[x] 字体为阿里巴巴普惠体 2.0</li><li>[x] 结尾显示水墨头像</li><li>[x] GitHub Pages 在线可访问</li><li>[x] README 包含项目说明和使用方式</li></ul><h2 id="遇到的问题" tabindex="-1">遇到的问题 <a class="header-anchor" href="#遇到的问题" aria-label="Permalink to &quot;遇到的问题&quot;">​</a></h2><h3 id="css-3d-transform-导致节点压扁" tabindex="-1">CSS 3D Transform 导致节点压扁 <a class="header-anchor" href="#css-3d-transform-导致节点压扁" aria-label="Permalink to &quot;CSS 3D Transform 导致节点压扁&quot;">​</a></h3><p><strong>问题</strong>：节点作为 3D-transformed div 在球体旋转时被透视压扁变形。</p><p><strong>解决</strong>：完全放弃 CSS 3D Transform，改为纯 JS 软件 3D 投影。手动计算旋转矩阵（Y 轴旋转 → X 轴旋转 → 透视投影），节点用 2D <code>translate(x, y)</code> 定位，只同步位置不参与 3D 翻转。</p><h3 id="性能卡顿-69000-次-dom-更新-帧" tabindex="-1">性能卡顿（69000 次 DOM 更新/帧） <a class="header-anchor" href="#性能卡顿-69000-次-dom-更新-帧" aria-label="Permalink to &quot;性能卡顿（69000 次 DOM 更新/帧）&quot;">​</a></h3><p><strong>问题</strong>：260 个粒子各自绑定 <code>onUpdate: apply()</code> 回调，每帧触发 260 次完整 DOM 更新。</p><p><strong>解决</strong>：改用 <code>gsap.ticker.add(formTick)</code> 单帧回调，每帧只调用一次 <code>apply()</code> 统一更新所有粒子和装饰元素。</p><h3 id="放大动画瞬间跳变" tabindex="-1">放大动画瞬间跳变 <a class="header-anchor" href="#放大动画瞬间跳变" aria-label="Permalink to &quot;放大动画瞬间跳变&quot;">​</a></h3><p><strong>问题</strong>：退出旧场景和新场景的 <code>camS</code> tween 各自创建临时对象 <code>{s: camS}</code>，timeline 创建时 <code>camS=1.3</code>，新场景 tween 从 1.3→1.3 无渐变。</p><p><strong>解决</strong>：在 <code>goScene()</code> 开头创建共享对象 <code>const camObj = {s: camS}</code>，退出和新场景的 tween 都操作同一对象，退出 tween 先把值归 1，新场景 tween 再从 1 渐变到 1.3。</p><h3 id="github-大文件警告" tabindex="-1">GitHub 大文件警告 <a class="header-anchor" href="#github-大文件警告" aria-label="Permalink to &quot;GitHub 大文件警告&quot;">​</a></h3><p><strong>问题</strong>：<code>s2w1.mov</code>（67MB）超过 GitHub 建议的 50MB 上限。</p><p><strong>解决</strong>：文件仍在 100MB 硬限制内，推送成功。GitHub 发出警告但未阻止。如果后续需要更大文件，可考虑 Git LFS。</p><h2 id="安全与限制" tabindex="-1">安全与限制 <a class="header-anchor" href="#安全与限制" aria-label="Permalink to &quot;安全与限制&quot;">​</a></h2><ul><li><strong>本地文件访问</strong>：WorkBuddy 需要读取本地素材文件夹，确保路径正确且文件无敏感信息。</li><li><strong>GitHub 推送</strong>：推送前确认 <code>.gitignore</code> 排除了 <code>node_modules</code>、构建产物和 <code>.workbuddy</code> 工作区数据。</li><li><strong>GitHub API</strong>：启用 Pages 需要 personal access token，不要将 token 提交到仓库。</li><li><strong>媒体版权</strong>：确保推送的视频和截图拥有发布权限，本项目中的作品均为自有内容。</li><li><strong>在线预览</strong>：GitHub Pages 为公开访问，确认内容可以公开展示。</li></ul><h2 id="可以怎样复用" tabindex="-1">可以怎样复用 <a class="header-anchor" href="#可以怎样复用" aria-label="Permalink to &quot;可以怎样复用&quot;">​</a></h2><p>这个案例的方法可以迁移到多种场景：</p><ul><li><strong>替换内容</strong>：把脚本和素材换成自己的作品集，即可生成个人 Showreel。</li><li><strong>调整视觉</strong>：修改 <code>--fd</code> / <code>--fb</code> / <code>--fm</code> CSS 变量切换字体，修改 <code>--bg</code> / <code>--ink</code> / <code>--soft</code> 切换配色。</li><li><strong>增减场景</strong>：在 <code>SCENES</code> 数组中增删条目，调整 <code>NIDX</code> 节点索引即可。</li><li><strong>换 3D 效果</strong>：修改 <code>project()</code> 函数的投影参数或 <code>genSphere()</code> 的分布算法，可以产生不同的球体形态。</li><li><strong>迁移到其他框架</strong>：核心的 3D 投影逻辑是纯 JS，可以移植到 React/Vue 组件中。</li></ul><p>关键经验：</p><ol><li><strong>先描述效果，再描述实现</strong>：告诉 WorkBuddy 你想要什么视觉效果，而不是直接指定技术方案。它会在尝试中找到最优解（比如从 CSS 3D 到软件投影的转变）。</li><li><strong>一轮一个反馈点</strong>：每次只反馈一个最突出的问题，避免同时改太多导致难以定位。</li><li><strong>用 <code>sips</code> / <code>ffprobe</code> 验证事实</strong>：涉及像素尺寸、视频比例等客观参数时，用命令行工具获取实际值，而不是凭目测。</li><li><strong>共享对象避免 tween 状态丢失</strong>：GSAP timeline 中多个 tween 操作同一变量时，必须使用共享对象而非各自创建临时对象。</li></ol>',68)])])}const k=a(l,[["render",r]]);export{b as __pageData,k as default};
